loops-nested-n1-coordinate-finder._solution:
def find_element_coordinates(grid, target):
    if not grid or not grid[0]:
        return []
    coordinates = []
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == target:
                coordinates.append([r, c])
    return coordinates

nested-loops-n2-count-matches._solution:
def count_matches(grid, target):
    count = 0
    for row in grid:
        for cell in row:
            if cell == target:
                count += 1
    return count

